/**
 * App-level MD3 themes (`newsprint` | `light` | `dark` | `system`) for `react-native-paper`,
 * paired with derived React Navigation themes.
 *
 * Architecture & Performance:
 * - Themes are lazily initialized as singletons to preserve reference stability and avoid
 *   unnecessary re-renders across the component tree.
 *
 * Palette Source of Truth:
 * - The palettes below are FROZEN hex literals. They were generated by the previous seed-based
 *   builder (`SchemeSpec` + `LIGHT_TONES`/`DARK_TONES` + `buildColors`) and are now checked in
 *   verbatim; no color math runs at runtime anymore.
 * - Regeneration recipe (only if seeds must change): rebuild the HSL→hex / mix / WCAG-contrast
 *   pipeline, evaluate it once offline (e.g. `node`), and paste the resulting hex values back in.
 *   Alpha tokens (`surfaceDisabled` / `onSurfaceDisabled` / `backdrop`) are 8-digit `#RRGGBBAA`.
 *
 * Tonal & Contrast Rules (already baked into the literals):
 * - Accents (`primary`, etc.): Tone ~0.36 in light modes (ensuring >=5:1 contrast with white
 *   `onPrimary`); tone ~0.72 in dark mode (paired with deep ink `onPrimary`).
 * - Containers: Tone ~0.78 (light) / ~0.28 (dark), with `onContainer` at ~0.16 / ~0.90.
 *   Carries higher chroma than `surfaceVariant` and maintains >=1.4:1 contrast against the background.
 * - Neutrals & Surfaces: Low-chroma ramps tinted with the theme's core hue. `surfaceVariant`,
 *   `outline`, and `elevation` derive from this shared source to completely eliminate residual purple.
 * - Elevation (`level1`–`level5`): `surface` blended with `primary` (4%–14% in light
 *   modes; 10%–30% in dark mode) to create cohesive, theme-tinted surface depth.
 */
import { MD3LightTheme, MD3DarkTheme, type MD3Theme } from "react-native-paper"
import { DefaultTheme as NavLightTheme, DarkTheme as NavDarkTheme, type Theme as NavigationTheme } from "@react-navigation/native"
import { useMemo } from "react"
import { useColorScheme, type ColorSchemeName } from "react-native"
import { useSnapshot } from "valtio"
import { lazyInit } from "../core/lazy"
import { settings, type ThemeMode } from "../state/settings"

export type { MD3Theme }

/** Base MD3 theme + the app-wide font scale in effect. Every theme produced by useActiveTheme carries fontScale. */
export type AppTheme = MD3Theme & { fontScale: number }

