export const kLightTheme = lazyInit<MD3Theme>(() => ({ ...MD3LightTheme, colors: LIGHT_COLORS }))

export const kNewsprintTheme = lazyInit<MD3Theme>(() => ({ ...MD3LightTheme, colors: NEWS_PRINT_COLORS }))

export const kDarkTheme = lazyInit<MD3Theme>(() => ({ ...MD3DarkTheme, colors: DARK_COLORS }))

export type ThemeName = "newsprint" | "light" | "dark"

/** Preference + system appearance → actual theme (system: dark system → dark, light system → newsprint) */
export function resolveThemeName(mode: ThemeMode, systemScheme: ColorSchemeName): ThemeName {
  if (mode === "dark") return "dark"
  if (mode === "light") return "light"
  if (mode === "newsprint") return "newsprint"
  return systemScheme === "dark" ? "dark" : "newsprint"
}

/** Bake the app-wide font scale into a base theme: Paper's MD3Typescale (theme.fonts) + a fontScale field for hardcoded point sizes. */
function applyFontScale(base: MD3Theme, scale: number): AppTheme {
  if (scale === 1) return { ...base, fontScale: 1 }
  const fonts = Object.fromEntries(
    Object.entries(base.fonts).map(([key, token]) => {
      const t = token as { fontSize: number; lineHeight: number }
      return [key, { ...t, fontSize: Math.max(8, Math.round(t.fontSize * scale)), lineHeight: Math.round(t.lineHeight * scale) }]
    })
  ) as unknown as MD3Theme["fonts"]
  return { ...base, fontScale: scale, fonts }
}

/** Cache keyed by theme name + scale so components keep stable theme references across re-renders. */
const scaledThemeCache = new Map<string, AppTheme>()

function getScaledTheme(name: ThemeName, scale: number): AppTheme {
  const key = `${name}:${scale}`
  const hit = scaledThemeCache.get(key)
  if (hit) return hit
  const base = name === "dark" ? kDarkTheme() : name === "light" ? kLightTheme() : kNewsprintTheme()
  const themed = applyFontScale(base, scale)
  scaledThemeCache.set(key, themed)
  return themed
}

/** Hook: current Paper theme from settings.themeMode + settings.fontScale + system appearance (stable reference) */
export function useActiveTheme(): AppTheme {
  const systemScheme = useColorScheme()
  const snap = useSnapshot(settings)
  return getScaledTheme(resolveThemeName(snap.themeMode, systemScheme), snap.fontScale)
}

/** Scale a hardcoded point size by the active theme's font scale (identity when the theme carries no scale). */
export function fs(theme: MD3Theme, px: number): number {
  const scale = (theme as Partial<AppTheme>).fontScale ?? 1
  if (!(scale > 0) || scale === 1) return px
  return Math.max(8, Math.round(px * scale))
}

/** Derive the react-navigation theme from the Paper theme so native headers/page backgrounds follow light/dark */
export function buildNavigationTheme(theme: MD3Theme): NavigationTheme {
  const base = theme.dark ? NavDarkTheme : NavLightTheme
  return {
    ...base,
    colors: {
      ...base.colors,
      primary: theme.colors.primary,
      background: theme.colors.background,
      card: theme.colors.elevation.level3,
      text: theme.colors.onSurface,
      border: theme.colors.outlineVariant,
      notification: theme.colors.error,
    },
  }
}

/** Hook: navigation theme kept in sync with the current Paper theme */
export function useNavigationTheme(): NavigationTheme {
  const theme = useActiveTheme()
  return useMemo(() => buildNavigationTheme(theme), [theme])
}
